// Contenido del popup para cada feature
function popupContentCenso(feature) {
    return (
        "<div id='Estilo1'><h3>Descripción</h3></div>" +
        "<hr class='hrx' style='color: #ef7d26;' align='left' noshade='noshade' size='0.5' width='100%' />" +
        "<div id='Estilo3a'>" +
        "<b> Provincia : </b>" + feature.properties.provincia + "<br>" +
        "<b> Departamento : </b>" + feature.properties.nam + "<br>" +
"<b> Total de Pob. : </b>" + feature.properties.value + "<br>" +
"<br>" +
"<b> Fuente : </b> INDEC " + "<br>" +
"<b> Años de publicación : </b> 2022 " + "<br>" +
"<b> Link : </b> https://portalgeoestadistico.indec.gob.ar" + "<br>" +
"<br>" +
    "</div>"
    );
}
function getColorCenso(value) {
    {
        if (value >= 1 && value <= 10661) return "#f6eff7";
        if (value > 10661 && value <= 20914) return "#accdcd";
        if (value > 20914 && value <= 44406) return "#82a3a3";
        if (value > 44406 && value <= 115340) return "#587979";
        if (value > 115340 && value <= 1841247) return "#2f4f4f";
        if (value > 1841247 ) return "#2f4f4f";
    }
};



function styleCenso(feature) {
    return {
        fillColor: getColorCenso(feature.properties.value),
        weight: 1,
        opacity: 1,
        color: 'gray',
        dashArray: '0',
        fillOpacity: 0.9
    }
}

// Función para generar la leyenda
function createLegendCenso() {
    var legend = L.control({ position: 'bottomright' });

    legend.onAdd = function () {
        var div = L.DomUtil.create('div', 'info legend');
        var labels = [];
        var styles = [
            { label: 'Total pob. (2022)', color: '' },
            { label: '1 - 10.661', color: '#f6eff7' },
            { label: '10.661 - 20.914', color: '#bdc9e1' },
            { label: '20.914 - 44.406', color: '#67a9cf' },
            { label: '44.406 - 115.340', color: '#1c9099' },
            { label: '115.340 - 1.841.247', color: '#016c59' },
        
            // Agrega aquí el resto de estilos con su respectiva etiqueta y color
        ];

        // Genera el contenido HTML de la leyenda
        styles.forEach(function (style) {
            labels.push(
                '<i style="background:' + style.color + '"></i> ' + style.label
            );
        });

        div.innerHTML = labels.join('<br>');
        return div;
    };

    // Función para mostrar/ocultar la leyenda
    function toggleLegend() {
        if (map.hasLayer(DataCenso)) {
            legend.addTo(map);
        } else {
            legend.remove();
        }
    }
// Eliminar la leyenda al inicio
legend.remove();
    // Escucha el cambio de estado de la capa
    map.on('overlayadd overlayremove', toggleLegend);
}



